<?php
require_once __DIR__.'/verificar_sesion.php';$db=conexion();$mensaje='';$error='';
$estados=array('Pendiente','Confirmado','En preparación','Enviado','Entregado','Cancelado');
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_validar($_POST['csrf']??''))$error='Formulario vencido. Recarga la página.';else{$id=(int)($_POST['pedido_id']??0);$estado=$_POST['estado']??'';if(!in_array($estado,$estados,true))$error='Estado no válido.';else{$up=$db->prepare('UPDATE pedidos SET estado=? WHERE id=?');$up->bind_param('si',$estado,$id);if($up->execute())$mensaje='Estado del pedido actualizado.';else$error='No se pudo actualizar el pedido.';$up->close();}}}
$res=$db->query('SELECT p.id,p.fecha,p.total,p.estado,p.telefono_entrega,p.direccion_entrega,p.barrio,p.ciudad,p.departamento,p.codigo_postal,p.metodo_pago,CONCAT(c.nombre," ",c.apellidos) AS cliente,c.correo FROM pedidos p INNER JOIN clientes c ON c.id=p.cliente_id ORDER BY p.fecha DESC');
$titulo='Pedidos';require __DIR__.'/includes/encabezado.php';
?>
<main class="contenido"><h1>Pedidos</h1><?php if($mensaje):?><p class="aviso"><?php echo e($mensaje);?></p><?php endif;?><?php if($error):?><p class="error"><?php echo e($error);?></p><?php endif;?>
<?php if(!$res->num_rows):?><p>Aún no hay pedidos registrados.</p><?php else:?><div class="tabla-scroll"><table><thead><tr><th>Pedido / cliente</th><th>Entrega</th><th>Total</th><th>Pago</th><th>Estado</th></tr></thead><tbody>
<?php while($p=$res->fetch_assoc()):?><tr><td><a href="pedido_detalle.php?id=<?php echo (int)$p['id'];?>">Ver #<?php echo (int)$p['id'];?></a> · <?php echo e($p['cliente']);?><br><?php echo e($p['correo']);?><br><small><?php echo e($p['fecha']);?></small></td><td><?php echo e($p['telefono_entrega']);?><br><?php echo e($p['direccion_entrega'].', '.$p['barrio'].', '.$p['ciudad'].', '.$p['departamento'].' '.$p['codigo_postal']);?></td><td><?php echo e(precio_texto($p['total']));?></td><td><?php echo e($p['metodo_pago']);?></td><td><form method="post" class="estado-pedido"><input type="hidden" name="csrf" value="<?php echo e(csrf_token());?>"><input type="hidden" name="pedido_id" value="<?php echo (int)$p['id'];?>"><select name="estado"><?php foreach($estados as $e):?><option <?php echo $p['estado']===$e?'selected':'';?>><?php echo e($e);?></option><?php endforeach;?></select><button class="boton" type="submit">Guardar</button></form></td></tr><?php endwhile;?></tbody></table></div><?php endif;?></main>
<?php $db->close();require __DIR__.'/includes/pie.php';?>
